import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';

const repository = '/home/df/wd/puni/puni-00';
const profilePath = 'openspec/schemas/twilight-v1/execution.yaml';
const execution = Bun.YAML.parse(readFileSync(resolve(repository, profilePath), 'utf8'));
const schema = Bun.YAML.parse(readFileSync(resolve(repository, 'openspec/schemas/twilight-v1/schema.yaml'), 'utf8'));
const artifactIds = new Set(schema.artifacts.map(artifact => artifact.id));
const stageOrder = ['request', 'discovery', 'specification', 'planning', 'implementation', 'review', 'verification', 'acceptance', 'handoff', 'release'];

function inspectProfile(definition) {
  const stages = new Map(definition.stages.map(stage => [stage.id, stage]));
  const catalog = new Map(definition.activities.map(activity => [activity.id, activity]));
  assert.equal(stages.size, definition.stages.length, 'duplicate stage');
  assert.equal(catalog.size, definition.activities.length, 'duplicate activity');
  const visited = new Set();
  const visiting = new Set();
  function visit(stageId) {
    assert(stages.has(stageId), `undeclared stage ${stageId}`);
    assert(!visiting.has(stageId), `stage cycle ${stageId}`);
    if (visited.has(stageId)) return;
    visiting.add(stageId);
    const stage = stages.get(stageId);
    assert(Array.isArray(stage.after), `missing stage edges ${stageId}`);
    stage.after.forEach(visit);
    for (const artifactId of [...(stage.artifacts ?? []), ...(stage.artifact ? [stage.artifact] : [])]) {
      assert(artifactIds.has(artifactId), `unknown artifact ${artifactId}`);
    }
    visiting.delete(stageId);
    visited.add(stageId);
  }
  definition.stages.forEach(stage => visit(stage.id));
  for (let position = 1; position < stageOrder.length; position++) {
    assert(stages.get(stageOrder[position]).after.includes(stageOrder[position - 1]), `missing shipped edge ${stageOrder[position - 1]} -> ${stageOrder[position]}`);
  }
  assert.equal(stages.get('release').command, 'release', 'release requires a command');
  const events = new Set(['beforeStage', 'afterStage', 'beforeActivity', 'afterActivity', 'beforeTool', 'afterTool', 'onFinding', 'onApproval', 'onRework', 'onFailure', 'onCancel', 'onTrigger', 'onProfileChange']);
  for (const point of [...Object.keys(definition.policies), ...definition.hooks.flatMap(hook => hook.at)]) {
    const separator = point.indexOf('.');
    const event = point.slice(0, separator);
    const subject = point.slice(separator + 1);
    assert(events.has(event), `unknown event ${point}`);
    if (event === 'onTrigger' || event === 'onProfileChange') {
      assert.equal(subject, '*', `invalid event target ${point}`);
    } else {
      assert(subject === '*' || stages.has(subject) || catalog.has(subject), `unknown lifecycle target ${point}`);
    }
  }
  assert(!('rateCard' in definition), 'organization rate card embedded in repository');
  assert.deepEqual(definition.policies['beforeActivity.*'].admission, { resourcesFrom: 'activity', budgetFrom: 'run' }, 'implicit agent-resource wildcard');
  for (const [activityId, pool] of [['verification.gate', 'build'], ['verification.browser', 'browser'], ['handoff.evaluate', 'build']]) {
    assert.equal(catalog.get(activityId).resources[pool], 1, `missing resource ${activityId}.${pool}`);
    assert(!('agent' in catalog.get(activityId).resources), `tool requires agent ${activityId}`);
  }
  assert.equal(definition.quality.id, 'delivery-baseline', 'initial evaluation missing');
  assert(definition.quality.observationSet.some(observation => observation.activity === 'handoff.evaluate'), 'independent evaluator not bound');
  for (const observation of definition.quality.observationSet) assert(catalog.has(observation.activity), `unknown observer ${observation.activity}`);
  const profileNames = Object.keys(definition.profiles).filter(name => name !== 'default');
  assert(profileNames.includes(definition.profiles.default), 'default profile missing');
  for (const name of profileNames) {
    const profile = definition.profiles[name];
    assert.deepEqual(Object.keys(profile.activities).sort(), [...catalog.keys()].sort(), `incomplete activity map ${name}`);
    for (const legacy of ['skip', 'review', 'verification']) assert(!(legacy in profile), `duplicate control ${name}.${legacy}`);
    for (const activity of definition.activities) {
      assert(stages.has(activity.stage), `unknown activity stage ${activity.id}`);
      assert(!('floor' in activity), `duplicate floor ${activity.id}`);
      const settings = profile.activities[activity.id];
      assert.equal(typeof settings.enabled, 'boolean', `missing enablement ${name}.${activity.id}`);
      if (activity.executor === 'tool') {
        assert.match(activity.implementation, /^registered:/, `unregistered tool ${activity.id}`);
        assert(!('model' in settings), `tool model ${name}.${activity.id}`);
      } else {
        assert.equal(activity.executor, 'agent', `unknown executor ${activity.id}`);
        if (settings.enabled) assert(settings.model ?? profile.models[activity.class], `unresolved agent model ${name}.${activity.id}`);
      }
    }
    for (const activityId of definition.repositoryFloor.activities) {
      assert(profile.activities[activityId].enabled, `disabled floor ${name}.${activityId}`);
    }
    assert.equal(profile.budget.scope, 'run', `budget scope ${name}`);
    assert(['model', 'delivery'].includes(profile.budget.moneyScope), `money scope ${name}`);
    assert(['strict', 'advisory'].includes(profile.budget.enforcement), `budget enforcement ${name}`);
    assert(!('elapsed' in profile.budget.limits), `ambiguous elapsed budget ${name}`);
    assert(profile.budget.limits.agentTime, `missing agent-time cap ${name}`);
    if (profile.budget.enforcement === 'advisory') assert(profile.budget.hardLimits, `advisory hard limits missing ${name}`);
    assert.equal(profile.activities['acceptance.cloud-browser'].enabled, false, `M1 cloud acceptance enabled ${name}`);
  }
  assert.equal(definition.profiles.fast.activities['review.judge'].enabled, false, 'fast judge enabled');
  assert.equal(definition.profiles.fast.activities['verification.browser'].enabled, false, 'fast browser enabled');
  assert.equal(definition.profiles.balanced.activities['verification.browser'].scope, 'affected', 'balanced browser scope');
  assert.equal(definition.profiles.thorough.activities['verification.browser'].scope, 'whole', 'thorough browser scope');
  return { stages: stages.size, activities: catalog.size, profiles: profileNames.length };
}

const positive = inspectProfile(execution);
const faults = [
  ['missing review edge', draft => { draft.stages.find(stage => stage.id === 'review').after = []; }, /missing shipped edge/],
  ['stage cycle', draft => { draft.stages.find(stage => stage.id === 'request').after = ['handoff']; }, /stage cycle/],
  ['legacy schedule target', draft => { draft.policies['onTrigger.schedule'] = draft.policies['onTrigger.*']; delete draft.policies['onTrigger.*']; }, /invalid event target/],
  ['duplicate skip switch', draft => { draft.profiles.fast.skip = ['review.judge']; }, /duplicate control/],
  ['missing agent assignment', draft => { delete draft.profiles.fast.models.implement; }, /unresolved agent model/],
  ['disabled mandatory gate', draft => { draft.profiles.fast.activities['verification.gate'].enabled = false; }, /disabled floor/],
  ['unproven cloud acceptance', draft => { draft.profiles.fast.activities['acceptance.cloud-browser'].enabled = true; }, /M1 cloud acceptance/],
  ['embedded organization prices', draft => { draft.rateCard = {}; }, /organization rate card embedded/],
  ['advisory without hard caps', draft => { draft.profiles.fast.budget.enforcement = 'advisory'; }, /advisory hard limits missing/],
  ['missing browser resource', draft => { delete draft.activities.find(activity => activity.id === 'verification.browser').resources.browser; }, /missing resource/],
  ['all tools charged agent slots', draft => { draft.policies['beforeActivity.*'].admission = { pools: ['agent'], budgetFrom: 'profile' }; }, /implicit agent-resource wildcard/],
  ['unbound independent evaluator', draft => { draft.quality.observationSet = draft.quality.observationSet.filter(observation => observation.activity !== 'handoff.evaluate'); }, /independent evaluator not bound/],
];
const negatives = faults.map(([name, inject, expected]) => {
  const draft = structuredClone(execution);
  inject(draft);
  assert.throws(() => inspectProfile(draft), expected, name);
  return { name, detected: true };
});
inspectProfile(execution);

const changed = execFileSync('git', ['diff', '--name-only', 'HEAD'], { cwd: repository, encoding: 'utf8' }).trim().split('\n');
let localLinks = 0;
for (const pathname of changed.filter(pathname => pathname.endsWith('.md'))) {
  const markdown = readFileSync(resolve(repository, pathname), 'utf8');
  for (const match of markdown.matchAll(/\[[^\]\n]+\]\(([^\s)]+)(?:\s+"[^"]*")?\)/g)) {
    const target = match[1];
    if (/^(?:https?:|mailto:|#)/.test(target)) continue;
    const [localPath] = target.split('#');
    assert(existsSync(resolve(repository, dirname(pathname), decodeURIComponent(localPath))), `broken link ${pathname}: ${target}`);
    localLinks++;
  }
}
const tasks = readFileSync(resolve(repository, 'openspec/changes/twilight-control-plane/tasks.md'), 'utf8');
assert.equal((tasks.match(/^- \[x\]/gm) ?? []).length, 0, 'product work claimed complete');
console.log(JSON.stringify({ boundary: 'temporary documentation probe; not the production compiler or runtime', positive, negatives, localLinks, productTasksUnchecked: (tasks.match(/^- \[ \]/gm) ?? []).length }, null, 2));
